CREATE TABLE "accounts" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "verified" BOOLEAN NOT NULL DEFAULT false, "role" TEXT NOT NULL DEFAULT 'participant', "disabled" BOOLEAN NOT NULL DEFAULT false, "createdAt" TEXT NOT NULL, "mfaSecret" TEXT, "mfaEnabled" BOOLEAN NOT NULL DEFAULT false, "mfaLastStep" INTEGER NOT NULL DEFAULT 0, "notifications" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "account_sessions" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "accounts"("id"), "expiresAt" TEXT NOT NULL, "createdAt" TEXT NOT NULL, "label" TEXT NOT NULL, "revoked" BOOLEAN NOT NULL DEFAULT false);
CREATE INDEX "account_sessions_userId_idx" ON "account_sessions"("userId");
CREATE TABLE "account_tokens" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "accounts"("id"), "kind" TEXT NOT NULL, "expiresAt" TEXT NOT NULL, "used" BOOLEAN NOT NULL DEFAULT false);
CREATE INDEX "account_tokens_userId_idx" ON "account_tokens"("userId");
CREATE TABLE "memberships" ("id" TEXT PRIMARY KEY, "tournamentId" INTEGER NOT NULL REFERENCES "tournaments"("id"), "userId" TEXT NOT NULL REFERENCES "accounts"("id"), "playerId" TEXT REFERENCES "players"("id"), "kind" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'participant', "status" TEXT NOT NULL DEFAULT 'pending', "checkedIn" BOOLEAN NOT NULL DEFAULT false, "createdAt" TEXT NOT NULL, UNIQUE("tournamentId","userId"));
CREATE TABLE "team_members" ("id" TEXT PRIMARY KEY, "playerId" TEXT NOT NULL REFERENCES "players"("id"), "userId" TEXT NOT NULL REFERENCES "accounts"("id"), "role" TEXT NOT NULL, "accepted" BOOLEAN NOT NULL DEFAULT false, UNIQUE("playerId","userId"));
CREATE TABLE "wallets" ("id" TEXT PRIMARY KEY, "tournamentId" INTEGER NOT NULL REFERENCES "tournaments"("id"), "userId" TEXT NOT NULL REFERENCES "accounts"("id"), "available" INTEGER NOT NULL DEFAULT 0 CHECK ("available">=0), "reserved" INTEGER NOT NULL DEFAULT 0 CHECK ("reserved">=0), UNIQUE("tournamentId","userId"));
CREATE TABLE "ledger_entries" ("id" TEXT PRIMARY KEY, "walletId" TEXT NOT NULL REFERENCES "wallets"("id"), "key" TEXT NOT NULL UNIQUE, "kind" TEXT NOT NULL, "availableDelta" INTEGER NOT NULL, "reservedDelta" INTEGER NOT NULL, "reason" TEXT NOT NULL, "actorId" TEXT NOT NULL, "createdAt" TEXT NOT NULL);
CREATE INDEX "ledger_entries_walletId_idx" ON "ledger_entries"("walletId");
CREATE TABLE "prediction_markets" ("id" TEXT PRIMARY KEY, "tournamentId" INTEGER NOT NULL REFERENCES "tournaments"("id"), "stageId" INTEGER NOT NULL, "matchId" INTEGER NOT NULL, "state" TEXT NOT NULL DEFAULT 'open', "homeId" TEXT NOT NULL, "awayId" TEXT NOT NULL, "lockedAt" TEXT, "winner" TEXT, "settledAt" TEXT, UNIQUE("tournamentId","stageId","matchId"));
CREATE TABLE "predictions" ("id" TEXT PRIMARY KEY, "marketId" TEXT NOT NULL REFERENCES "prediction_markets"("id"), "userId" TEXT NOT NULL REFERENCES "accounts"("id"), "side" TEXT NOT NULL CHECK ("side" IN ('home','away')), "stake" INTEGER NOT NULL CHECK ("stake">=0), "payout" INTEGER NOT NULL DEFAULT 0 CHECK ("payout">=0), "status" TEXT NOT NULL DEFAULT 'reserved', "updatedAt" TEXT NOT NULL, UNIQUE("marketId","userId"));
CREATE TABLE "match_submissions" ("id" TEXT PRIMARY KEY, "tournamentId" INTEGER NOT NULL REFERENCES "tournaments"("id"), "matchId" INTEGER NOT NULL, "userId" TEXT NOT NULL REFERENCES "accounts"("id"), "homeScore" INTEGER NOT NULL CHECK ("homeScore">=0), "awayScore" INTEGER NOT NULL CHECK ("awayScore">=0), "evidence" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "response" TEXT NOT NULL DEFAULT '', "createdAt" TEXT NOT NULL);
CREATE INDEX "match_submissions_tournamentId_matchId_idx" ON "match_submissions"("tournamentId","matchId");
